// AccountFilter provides filtering for Account queries
type AccountFilter struct {
	Id              *UUIDFilter
	Name            *StringFilter
	Status          *StringFilter
	StatusEnteredAt *DateTimeFilter
	Version         *Int64Filter
	// WorkspaceID allows filtering by foreign key
	WorkspaceID *UUIDFilter
	// Workspace keeps the rows whose workspace is among the Workspace rows
	// the filter finds (D90): one condition, the foreign key in the keys of
	// those rows.
	Workspace *WorkspaceFilter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []AccountFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []AccountFilter
}

// AccountUpdate provides fields that can be updated
type AccountUpdate struct {
	Name *string
	// WorkspaceID allows updating the foreign key for workspace
	WorkspaceID *types.IdentityUUID
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewAccountSnapshotUpdate maps every mutable field from a complete
// Account value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewAccountSnapshotUpdate(input *types.Account) *AccountUpdate {
	update := &AccountUpdate{}
	if input == nil {
		return update
	}
	update.Name = &input.Name
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *AccountUpdate) ApplyTo(row *types.Account) {
	if u == nil || row == nil {
		return
	}
	if u.Name != nil {
		row.Name = *u.Name
	}
	if u.WorkspaceID != nil {
		row.Workspace.Id = u.WorkspaceID
	}
}

// AccountFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func AccountFilterConditions(filter *AccountFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a AccountFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *AccountFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

// conditions are the filter's conditions, each value appended to args, its
// placeholder numbered from paramOffset+1.
func (f *AccountFilter) conditions(args *[]interface{}, paramOffset int) []string {
	if f == nil {
		return nil
	}

	var conditions []string
	paramNum := paramOffset
	if f.Id != nil {
		if f.Id.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.id = $%d`, paramNum))
			*args = append(*args, f.Id.Eq.ToUUID())
		}
		if len(f.Id.In) > 0 {
			placeholders := make([]string, len(f.Id.In))
			for i, id := range f.Id.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`account.id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.Id.IsNull != nil {
			if *f.Id.IsNull {
				conditions = append(conditions, `account.id IS NULL`)
			} else {
				conditions = append(conditions, `account.id IS NOT NULL`)
			}
		}
	}
	if f.Name != nil {
		if f.Name.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account."name" = $%d`, paramNum))
			*args = append(*args, *f.Name.Eq)
		}
		if len(f.Name.In) > 0 {
			placeholders := make([]string, len(f.Name.In))
			for i, value := range f.Name.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`account."name" IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.Name.ILike != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account."name" ILIKE $%d`, paramNum))
			*args = append(*args, "%"+*f.Name.ILike+"%")
		}
		if f.Name.IsNull != nil {
			if *f.Name.IsNull {
				conditions = append(conditions, `account."name" IS NULL`)
			} else {
				conditions = append(conditions, `account."name" IS NOT NULL`)
			}
		}
	}
	if f.Status != nil {
		if f.Status.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status = $%d`, paramNum))
			*args = append(*args, *f.Status.Eq)
		}
		if len(f.Status.In) > 0 {
			placeholders := make([]string, len(f.Status.In))
			for i, value := range f.Status.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`account.status IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.Status.ILike != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status ILIKE $%d`, paramNum))
			*args = append(*args, "%"+*f.Status.ILike+"%")
		}
		if f.Status.IsNull != nil {
			if *f.Status.IsNull {
				conditions = append(conditions, `account.status IS NULL`)
			} else {
				conditions = append(conditions, `account.status IS NOT NULL`)
			}
		}
	}
	if f.StatusEnteredAt != nil {
		if f.StatusEnteredAt.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at = $%d`, paramNum))
			*args = append(*args, *f.StatusEnteredAt.Eq)
		}
		if f.StatusEnteredAt.Gt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at > $%d`, paramNum))
			*args = append(*args, *f.StatusEnteredAt.Gt)
		}
		if f.StatusEnteredAt.Gte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at >= $%d`, paramNum))
			*args = append(*args, *f.StatusEnteredAt.Gte)
		}
		if f.StatusEnteredAt.Lt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at < $%d`, paramNum))
			*args = append(*args, *f.StatusEnteredAt.Lt)
		}
		if f.StatusEnteredAt.Lte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at <= $%d`, paramNum))
			*args = append(*args, *f.StatusEnteredAt.Lte)
		}
		if f.StatusEnteredAt.Between != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at >= $%d`, paramNum))
			*args = append(*args, f.StatusEnteredAt.Between.Start)
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at <= $%d`, paramNum))
			*args = append(*args, f.StatusEnteredAt.Between.End)
		}
		if len(f.StatusEnteredAt.In) > 0 {
			placeholders := make([]string, len(f.StatusEnteredAt.In))
			for i, value := range f.StatusEnteredAt.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`account.status_entered_at IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.StatusEnteredAt.IsNull != nil {
			if *f.StatusEnteredAt.IsNull {
				conditions = append(conditions, `account.status_entered_at IS NULL`)
			} else {
				conditions = append(conditions, `account.status_entered_at IS NOT NULL`)
			}
		}
	}
	if f.Version != nil {
		if f.Version.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version = $%d`, paramNum))
			*args = append(*args, *f.Version.Eq)
		}
		if f.Version.Gt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version > $%d`, paramNum))
			*args = append(*args, *f.Version.Gt)
		}
		if f.Version.Gte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version >= $%d`, paramNum))
			*args = append(*args, *f.Version.Gte)
		}
		if f.Version.Lt != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version < $%d`, paramNum))
			*args = append(*args, *f.Version.Lt)
		}
		if f.Version.Lte != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version <= $%d`, paramNum))
			*args = append(*args, *f.Version.Lte)
		}
		if f.Version.Between != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version >= $%d`, paramNum))
			*args = append(*args, f.Version.Between.Min)
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account._version <= $%d`, paramNum))
			*args = append(*args, f.Version.Between.Max)
		}
		if len(f.Version.In) > 0 {
			placeholders := make([]string, len(f.Version.In))
			for i, value := range f.Version.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, value)
			}
			conditions = append(conditions, fmt.Sprintf(`account._version IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.Version.IsNull != nil {
			if *f.Version.IsNull {
				conditions = append(conditions, `account._version IS NULL`)
			} else {
				conditions = append(conditions, `account._version IS NOT NULL`)
			}
		}
	}
	if f.WorkspaceID != nil {
		if f.WorkspaceID.Eq != nil {
			paramNum++
			conditions = append(conditions, fmt.Sprintf(`account.workspace_id = $%d`, paramNum))
			*args = append(*args, f.WorkspaceID.Eq.ToUUID())
		}
		if len(f.WorkspaceID.In) > 0 {
			placeholders := make([]string, len(f.WorkspaceID.In))
			for i, id := range f.WorkspaceID.In {
				paramNum++
				placeholders[i] = fmt.Sprintf("$%d", paramNum)
				*args = append(*args, id.ToUUID())
			}
			conditions = append(conditions, fmt.Sprintf(`account.workspace_id IN (%s)`, strings.Join(placeholders, ", ")))
		}
		if f.WorkspaceID.IsNull != nil {
			if *f.WorkspaceID.IsNull {
				conditions = append(conditions, `account.workspace_id IS NULL`)
			} else {
				conditions = append(conditions, `account.workspace_id IS NOT NULL`)
			}
		}
	}
	if f.Workspace != nil {
		before := len(*args)
		through := f.Workspace.conditions(args, paramNum)
		paramNum += len(*args) - before
		where := ""
		if len(through) > 0 {
			where = " WHERE " + strings.Join(through, " AND ")
		}
		conditions = append(conditions, fmt.Sprintf(`account.workspace_id IN (SELECT workspace.id FROM workspace%s)`, where))
	}

	// AllOf's filters' conditions are the filter's own, ANDed (D99), each
	// one's placeholders numbered after the last.
	for i := range f.AllOf {
		before := len(*args)
		conditions = append(conditions, f.AllOf[i].conditions(args, paramNum)...)
		paramNum += len(*args) - before
	}

	if len(f.AnyOf) > 0 {
		start := len(*args)
		branches := make([]string, 0, len(f.AnyOf))
		every := false
		for i := range f.AnyOf {
			before := len(*args)
			branch := f.AnyOf[i].conditions(args, paramNum)
			paramNum += len(*args) - before
			if len(branch) == 0 {
				every = true
				continue
			}
			branches = append(branches, "("+strings.Join(branch, " AND ")+")")
		}
		if every {
			// A branch of no condition keeps every row, and so does the
			// whole: the other branches' parameters go too. AnyOf is the
			// last condition, so no placeholder follows theirs.
			*args = (*args)[:start]
		} else {
			conditions = append(conditions, "("+strings.Join(branches, " OR ")+")")
		}
	}

	return conditions
}

