// SessionFilter provides filtering for Session queries
type SessionFilter struct {
	Id                 *UUIDFilter
	Device             *UUIDFilter
	Agent              *StringFilter
	PresenceDeadline   *DateTimeFilter
	PresenceLastBeatAt *DateTimeFilter
	PresenceMissed     *BoolFilter
	PresenceReleased   *StringFilter
	Status             *StringFilter
	StatusEnteredAt    *DateTimeFilter
	Version            *Int64Filter
	// AllOf keeps the rows every one of its filters finds, beside the
	// filter's other conditions (D99): each filter's conditions are ANDed
	// with them, so two AnyOf groups, each in a filter of its own, must
	// both hold. A filter of no condition adds none, and so does an empty
	// AllOf.
	AllOf []SessionFilter
	// AnyOf keeps the rows any of its filters finds, each filter's
	// conditions ANDed and the filters ORed, beside the filter's other
	// conditions (D90). A filter of no condition keeps every row, and so
	// does an empty AnyOf.
	AnyOf []SessionFilter
}

// SessionUpdate provides fields that can be updated
type SessionUpdate struct {
	Device *types.IdentityUUID
	Agent  *string
	// UpdatedBy is automatically set if not provided and user is in context
	UpdatedBy *types.IdentityUUID
}

// NewSessionSnapshotUpdate maps every mutable field from a complete
// Session value. It is intended for source-of-truth replacement flows;
// nullable zero values clear their columns instead of leaving stale data.
func NewSessionSnapshotUpdate(input *types.Session) *SessionUpdate {
	update := &SessionUpdate{}
	if input == nil {
		return update
	}
	update.Device = &input.Device
	update.Agent = &input.Agent
	return update
}

// ApplyTo writes every set and SetNull field onto row. A nil receiver or row
// is a no-op. SetNull wins when both a value and SetNull are present.
func (u *SessionUpdate) ApplyTo(row *types.Session) {
	if u == nil || row == nil {
		return
	}
	if u.Device != nil {
		row.Device = *u.Device
	}
	if u.Agent != nil {
		row.Agent = *u.Agent
	}
}

// SessionFilterConditions are the filter's conditions for a query of
// the caller's own, each column qualified by its table: each value is
// appended to args, its placeholder numbered after those already there.
// FindMany's WHERE is them joined by AND. A nil filter has none.
func SessionFilterConditions(filter *SessionFilter, args *[]any) []string {
	return filter.conditions(args, len(*args))
}

// buildWhereClause builds a WHERE clause from a SessionFilter: its
// conditions joined by AND, or nothing when it has none.
func (f *SessionFilter) buildWhereClause(args *[]interface{}, paramOffset int) string {
	conditions := f.conditions(args, paramOffset)
	if len(conditions) == 0 {
		return ""
	}
	return " WHERE " + strings.Join(conditions, " AND ")
}

